import CMigration
import Darwin

class ArchiveOps {

  let options : pax.CommandOptions

  init(options: pax.CommandOptions) {
    self.options = options
  }
  /*
   * Routines which control the overall operation modes of pax as specified by
   * the user: list, append, read ...
   */

  var hdbuf : [UInt8] = Array(repeating: 0, count: BLKMULT)		/* space for archive header on read */

  var cwdpath : String?        /* current working directory path */

  func updatepath() -> Result {
    let s : String? = withUnsafeTemporaryAllocation(of: UInt8.self, capacity: MAXPATHLEN) { p -> String? in
      guard let _ = getcwd(p.baseAddress!, p.count) else {
        Tty.syswarn(true, errno, "Cannot get working directory");
        return nil
      }
      return String(cString: p.baseAddress!)
    }
    if let s {
      cwdpath = s
    } else {
      return .failed
    }
    return .ok
  }

  func fdochdir(_ fcwd : FileDescriptor) -> Result {
    if (fchdir(fcwd.rawValue) == -1) {
      Tty.syswarn(true, errno, "Cannot chdir to `.'");
      return .failed
    }
    return updatepath();
  }

  func dochdir(_ name : String) -> Result {
    if (chdir(name) == -1) {
      Tty.syswarn(true, errno, "Cannot chdir to `\(name)'")
    }
    return updatepath();
  }

  private func path_check(_ arcn: ARCHD, _ level : Int) -> Result {
//    char buf[MAXPATHLEN];
//    char *p;

    if ((p = strrchr(arcn.name, '/')) == NULL) {
      return .ok
    }
    *p = '\0';

    if (realpath(arcn.name, buf) == NULL) {
      int error;
      error = path_check(arcn, level + 1);
      *p = '/';
      if (error == 0) {
        return .ok
      }
      if (level == 0) {
        Tty.syswarn(true, 0, "Cannot resolve `%s'", arcn.name);
      }
      return .failed
    }
    if (cwdpathlen == 1) {	/* We're in the root */
      *p = '/';
      return .ok
    }
    if ((strncmp(buf, cwdpath, cwdpathlen) != 0) || (buf[cwdpathlen] != '\0' && buf[cwdpathlen] != '/')) {
      *p = '/';
      Tty.syswarn(true, 0, "Attempt to write file `%s' that resolves into "
                  "`%s/%s' outside current working directory `%s' ignored",
                  arcn.name, buf, p + 1, cwdpath);
      return .failed
    }
    *p = '/';
    return .ok
  }

  /*
   * list()
   *	list the contents of an archive which match user supplied pattern(s)
   *	(no pattern matches all).
   */

  func list() {
    var arcn = ARCHD()
    /*
     * figure out archive type; pass any format specific options to the
     * archive option processing routine; call the format init routine. We
     * also save current time for ls_list() so we do not make a system
     * call for each file we need to print. If verbose (vflag) start up
     * the name and group caches.
     */
    if ((get_arc() < 0) || ((*frmt->options)() < 0) ||
        ((*frmt->st_rd)() < 0)) {
      return;
    }

    if (vflag && ((uidtb_start() < 0) || (gidtb_start() < 0))) {
      return;
    }

    let now = Darwin.time(nil)

    /*
     * step through the archive until the format says it is done
     */
    while (next_head(arcn) == 0) {

      if arcn.type == .GLL || arcn.type == .GLF {
        /*
         * we need to read, to get the real filename
         */
        var cnt = 0
        if !options.frmt!.rd_data(arcn, arcn.type == PAXType.GLF ? -1 : -2, &cnt) {
          rd_skip(cnt + arcn.pad)
        }
        continue;
      }

      /*
       * check for pattern, and user specified options match.
       * When all patterns are matched we are done.
       */
      if ((res = pat_match(arcn)) < 0) {
        break;
      }

      if ((res == 0) && (sel_chk(arcn) == 0)) {
        /*
         * pattern resulted in a selected file
         */
        if (pat_sel(arcn) < 0) {
          break;
        }

        /*
         * modify the name as requested by the user if name
         * survives modification, do a listing of the file
         */
        if ((res = mod_name(arcn)) < 0) {
          break;
        }
        if (res == 0) {
          ls_list(arcn, now, stdout);
        }
      }

      /*
       * skip to next archive format header using values calculated
       * by the format header read routine
       */
      if (rd_skip(arcn.skip + arcn.pad) == 1) {
        break;
      }
    }

    /*
     * all done, let format have a chance to cleanup, and make sure that
     * the patterns supplied by the user were all matched
     */
    options.frmt!.end_rd()
    sigprocmask(SIG_BLOCK, &s_mask, nil)
    ar_io.ar_close()
    pat_chk();
  }

  /*
   * extract()
   *	extract the member(s) of an archive as specified by user supplied
   *	pattern(s) (no patterns extracts all members)
   */

  func extract() {
 /*   int res;
    off_t cnt;
    struct stat sb;
    int fd;
*/

    int copyfile_disable = (getenv(COPYFILE_DISABLE_VAR) != NULL);
    LIST_HEAD(copyfile_list_t, copyfile_list_entry_t) copyfile_list;
    struct copyfile_list_entry_t {
      char *src;
      char *dst;
      LIST_ENTRY(copyfile_list_entry_t) link;
    } *cle;

    LIST_INIT(&copyfile_list);

    var arcn = ARCHD()
    /*
     * figure out archive type; pass any format specific options to the
     * archive option processing routine; call the format init routine;
     * start up the directory modification time and access mode database
     */
    if ((get_arc() < 0) || ((*frmt->options)() < 0) ||
        ((*frmt->st_rd)() < 0) || (dir_start() < 0)) {
      return;
    }

    /*
     * When we are doing interactive rename, we store the mapping of names
     * so we can fix up hard links files later in the archive.
     */
    if (iflag && (name_start() < 0)) {
      return;
    }

    let now = Darwin.time(nil)

    /*
     * step through each entry on the archive until the format read routine
     * says it is done
     */
    while !next_head(arcn) {

      if arcn.type == .GLL || arcn.type == .GLF {
        /*
         * we need to read, to get the real filename
         */
        var cnt = 0
        if !options.frmt!.rd_data(arcn, arcn.type == .GLF ? -1 : -2, &cnt) {
          rd_skip(cnt + arcn.pad)
        }
        continue
      }

      /*
       * check for pattern, and user specified options match. When
       * all the patterns are matched we are done
       */
      if ((res = pat_match(arcn)) < 0) {
        break;
      }

      if ((res > 0) || (sel_chk(arcn) != 0)) {
        /*
         * file is not selected. skip past any file data and
         * padding and go back for the next archive member
         */
        (void)rd_skip(arcn.skip + arcn.pad);
        continue;
      }

      /*
       * with -u or -D only extract when the archive member is newer
       * than the file with the same name in the file system (no
       * test of being the same type is required).
       * NOTE: this test is done BEFORE name modifications as
       * specified by pax. this operation can be confusing to the
       * user who might expect the test to be done on an existing
       * file AFTER the name mod. In honesty the pax spec is probably
       * flawed in this respect.
       */
