            continue;
          }
        } else if (arcn.sb.lastModified <= sb.lastModified) {
          (void)rd_skip(arcn.skip + arcn.pad);
          continue;
        }
      }

      if (vflag) {
        if (vflag > 1) {
          ls_list(arcn, now, listf);
        }
        else {

          (void)safe_print(arcn.name, listf);

          vfpart = 1;
        }
      }

      /*
       * if required, chdir around.
       */
      if ((arcn.pat != NULL) && (arcn.pat->chdname != NULL)) {

        dochdir(arcn.pat->chdname);
      }
      if (secure && path_check(arcn, 0) != 0) {
        (void)rd_skip(arcn.skip + arcn.pad);
        continue;
      }

      /*
       * all ok, extract this member based on type
       */
      if ((arcn.type != PAX_REG) && (arcn.type != PAX_CTG)) {
        /*
         * process archive members that are not regular files.
         * throw out padding and any data that might follow the
         * header (as determined by the format).
         */
        if ((arcn.type == PAX_HLK) || (arcn.type == PAX_HRG)) {
          res = lnk_creat(arcn);
        }
        else {
          res = node_creat(arcn);
        }

        (void)rd_skip(arcn.skip + arcn.pad);
        if (res < 0) {
          purg_lnk(arcn);
        }

        if (vflag && vfpart) {
          (void)putc('\n', listf);
          vfpart = 0;
        }
        continue;
      }
      /*
       * we have a file with data here. If we can not create it, skip
       * over the data and purge the name from hard link table
       */
      if ((fd = file_creat(arcn)) < 0) {
        (void)rd_skip(arcn.skip + arcn.pad);
        purg_lnk(arcn);
        continue;
      }
      /*
       * extract the file from the archive and skip over padding and
       * any unprocessed data
       */
      res = (*frmt->rd_data)(arcn, fd, &cnt);
      file_close(arcn, fd);
      if (vflag && vfpart) {
        (void)putc('\n', listf);
        vfpart = 0;
      }
      if (!res) {
        (void)rd_skip(cnt + arcn.pad);
      }

      if (!strncmp(basename(arcn.name), "._", 2)) {
        cle = alloca(sizeof(struct copyfile_list_entry_t));
        cle->src = strdup(arcn.name);

        if (asprintf(&cle->dst, "%s/%s",
                     dirname(arcn.name), basename(arcn.name) + 2) != -1) {
          LIST_INSERT_HEAD(&copyfile_list, cle, link);
        } else {
          free(cle->src);
        }
      }

      /*
       * if required, chdir around.
       */
      if ((arcn.pat != NULL) && (arcn.pat->chdname != NULL)) {

        fdochdir(cwdfd);

      }
    }

    LIST_FOREACH(cle, &copyfile_list, link)
